css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); border-radius: 9999px; border: calc(var(--loader-size) * .035) solid color-mix(in srgb, var(--loader-color) 25%, transparent); animation: twOrbit calc(var(--loader-speed) * 1.6) linear infinite; }
.loader .dot { position: absolute; top: calc(var(--loader-size) * -.1); left: 50%; width: calc(var(--loader-size) * .22); height: calc(var(--loader-size) * .22); margin-left: calc(var(--loader-size) * -.11); border-radius: 9999px; background: var(--loader-color); box-shadow: 0 0 calc(var(--loader-size) * .12) color-mix(in srgb, var(--loader-color) 55%, transparent); }
@keyframes twOrbit { to { transform: rotate(360deg); } }
